import { RouteMap } from "@/components/route-map";
import { routes } from "@/lib/site-content";

/*
 * Route of operation: Goa to the intended operating regions.
 * The map (components/route-map.tsx, generated by scripts/create-route-map.py) is a self-contained figure
 * with its own legend and caption; every route is a separate <path id="route-…" pathLength="1">, ready to
 * be animated later (see the comment at the top of route-map.tsx).
 */
export function RoutesSection() {
  return (
    <section className="routes section section--mist" id="routes" aria-labelledby="routes-title">
      <span id="operating-areas" className="anchor-alias" aria-hidden="true" />
      <div className="wrap">
        <div className="section-heading">
          <div>
            <p className="eyebrow">{routes.eyebrow}</p>
            <h2 id="routes-title">{routes.title}</h2>
          </div>
          <p>{routes.body}</p>
        </div>

        <RouteMap caption={routes.caption} className="routes-map" />

        <ol className="route-legend" aria-label="Route of operation">
          <li className="route-origin">
            <span>{routes.origin.label}</span>
            <strong>{routes.origin.value}</strong>
          </li>
          {routes.regions.map((r, i) => (
            <li key={r.id}>
              <span>{String(i + 1).padStart(2, "0")}</span>
              <strong>{r.name}</strong>
            </li>
          ))}
        </ol>
      </div>
    </section>
  );
}
